-- IPA 2021-07-25 selected Q25–44, source-reviewed adaptations.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210725-q25','exam-fe','RDBMSスキーマ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問25・改編】RDBMSにおけるスキーマの説明はどれか。','[{"id":"a","text":"利用者の視点による仮想的な表"},{"id":"b","text":"データの性質、形式、他データとの関連などの定義の集合"},{"id":"c","text":"データの挿入、更新、削除、検索などの操作の総称"},{"id":"d","text":"データベースの一貫性を保持する各種制約条件の総称"}]','"b"','スキーマはデータ構造や関係などの定義を表す。中文：模式是数据结构、格式和数据关系等定义的集合。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q26','exam-fe','ハッシュインデックス','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問26・改編】売上（伝票番号、売上年月日、商品名、利用者ID、店舗番号、売上金額）表の検索で、B+木よりハッシュインデックスに適するものはどれか。','[{"id":"a","text":"売上金額が1万円以上の行を検索する"},{"id":"b","text":"売上年月日が今月の行を検索する"},{"id":"c","text":"商品名がDBで始まる行を検索する"},{"id":"d","text":"利用者IDが1001の行を検索する"}]','"d"','ハッシュは等価検索に適し、範囲や前方一致には順序を利用できるB+木が適する。中文：哈希索引适合精确相等查询，B+树适合范围或前缀查询。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q27','exam-fe','トランザクション','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問27・改編】データベースのトランザクションに関する適切な記述はどれか。','[{"id":"a","text":"他の更新を防ぐためロックを解放した"},{"id":"b","text":"障害で異常終了したトランザクションをDBMSがロールフォワードした"},{"id":"c","text":"更新を確定するためアプリケーションがロールバックした"},{"id":"d","text":"デッドロックが発生したためDBMSがトランザクションをロールバックした"}]','"d"','デッドロックの解消には一方を中止しロールバックしてロックを解放する方法がある。中文：发生死锁时，数据库可以回滚一个事务以释放锁。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q28','exam-fe','ロック粒度','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問28・改編】データベースのロック粒度について適切なものはどれか。','[{"id":"a","text":"更新時に粒度を大きくすると他のトランザクションの待ちが増えスループットが低下し得る"},{"id":"b","text":"同一データを更新する処理が多い場合、粒度を大きくすると同時実行数が増える"},{"id":"c","text":"表全体を参照する場合、粒度を大きくすると他の参照を妨げなくなる"},{"id":"d","text":"粒度を大きくすると1トランザクションがかけるロックの個数が多くなる"}]','"a"','大きな範囲を一度にロックすると競合が増える一方、通常ロックの個数は減る。中文：锁的粒度越大，冲突和等待可能增加，但锁的数量通常减少。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q29','exam-fe','データマイニング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問29・改編】大量のデータから統計的手法などで新たな傾向やパターンを見つけるプロセスはどれか。','[{"id":"a","text":"データウェアハウス"},{"id":"b","text":"データディクショナリ"},{"id":"c","text":"データマイニング"},{"id":"d","text":"メタデータ"}]','"c"','データマイニングは大量データから有用な知識や傾向を抽出する。中文：数据挖掘从大量数据中发现规律和有用知识。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q30','exam-fe','伝送時間','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問30・改編】100Mビット/秒のLANで1000バイトのレコードを1000件連続送信する。伝送効率50%のとき伝送時間は何秒か。','[{"id":"a","text":"0.02"},{"id":"b","text":"0.08"},{"id":"c","text":"0.16"},{"id":"d","text":"1.6"}]','"c"','1000×1000×8=800万ビット。実効速度は5000万ビット/秒なので0.16秒。中文：数据共800万比特，有效率50%时速率5000万比特每秒，耗时0.16秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q32','exam-fe','OSI層と中継装置','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問32・改編】OSI参照モデルの物理層、データリンク層、ネットワーク層で中継する装置をこの順に並べたものはどれか。','[{"id":"a","text":"ブリッジ、リピータ、ルータ"},{"id":"b","text":"ブリッジ、ルータ、リピータ"},{"id":"c","text":"リピータ、ブリッジ、ルータ"},{"id":"d","text":"リピータ、ルータ、ブリッジ"}]','"c"','リピータは物理層、ブリッジはデータリンク層、ルータはネットワーク層で中継する。中文：中继器、网桥、路由器分别工作于物理层、数据链路层、网络层。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q35','exam-fe','ソフトウェアのディジタル署名','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問35・改編】アプリケーションソフトウェアにディジタル署名を施す目的はどれか。','[{"id":"a","text":"利用者がソフトウェアの改ざんを検知できるようにする"},{"id":"b","text":"ソフトウェアの使用を特定の利用者に制限する"},{"id":"c","text":"著作権が作成者にあることを証明する"},{"id":"d","text":"利用者による修正や改変を不可能にする"}]','"a"','署名の検証によって、署名後の改ざんを検出できる。署名自体は改変を防止しない。中文：数字签名可用于检测签名后的篡改，本身不会阻止修改。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q36','exam-fe','DBアカウントと最小権限','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問36・改編】DBアカウントの種類と権限の組合せとして適切なものはどれか。レコード更新権限とテーブル作成・削除権限の順に示す。','[{"id":"a","text":"データ構造定義用：有、無"},{"id":"b","text":"データ構造定義用：無、有"},{"id":"c","text":"データ入力・更新用：有、有"},{"id":"d","text":"データ入力・更新用：無、有"}]','"b"','必要な権限だけを与える。構造定義用にはテーブル作成・削除権限を付け、更新権限は不要なら付けない。中文：遵循最小权限原则，定义结构的账号只授予需要的表结构权限。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q38','exam-fe','共通鍵暗号','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問38・改編】共通鍵暗号方式の特徴はどれか。','[{"id":"a","text":"共有鍵を事前に平文で送ることが推奨される"},{"id":"b","text":"通信相手が1人の場合、公開鍵暗号より使用する鍵の個数が多い"},{"id":"c","text":"同程度の暗号強度では公開鍵暗号より暗号化・復号の処理時間が短い"},{"id":"d","text":"鍵のペアを生成し片方で暗号化した文書を他方で復号する"}]','"c"','共通鍵暗号は一般に公開鍵暗号より高速だが、秘密鍵を安全に共有・管理する必要がある。中文：对称加密通常比公钥加密快，但必须安全共享和管理密钥。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q40','exam-fe','情報セキュリティの可用性','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問40・改編】ファイルサーバの可用性を高める管理策はどれか。','[{"id":"a","text":"ストレージを二重化し耐障害性を高める"},{"id":"b","text":"ディジタル証明書を使って利用者を認証する"},{"id":"c","text":"ファイルを暗号化して情報漏えいを防ぐ"},{"id":"d","text":"フォルダにアクセス権を設定して不正アクセスを防ぐ"}]','"a"','冗長化は障害時にもサービスを継続しやすくし、可用性を高める。中文：存储冗余提高故障时的服务持续能力，即可用性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q41','exam-fe','Web改ざん検知','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問41・改編】Webサーバのコンテンツ改ざんを検知する最も有効な方法はどれか。','[{"id":"a","text":"各ファイルの更新日時を保存し定期的に比較する"},{"id":"b","text":"各ファイルのハッシュ値を保存し定期的に再計算して比較する"},{"id":"c","text":"サーバのメモリ使用率を確認する"},{"id":"d","text":"HTTPとHTTPS以外の通信がないことを確認する"}]','"b"','信頼できる場所に保存したハッシュ値と再計算値を比較し内容の変更を検出する。中文：将文件重新计算的哈希值与可信保存值比较，以检测内容变化。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q42','exam-fe','IPS','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問42・改編】IPSの説明はどれか。','[{"id":"a","text":"暗号化・復号処理を高速化する専用ハードウェア"},{"id":"b","text":"不正通信を検知して遮断し、サーバやネットワークへの侵入を防ぐ装置"},{"id":"c","text":"疑似攻撃でシステムの脆弱性を見つけるツール"},{"id":"d","text":"指紋や虹彩による入室時の本人認証システム"}]','"b"','IPSは不正な通信を検知し遮断する侵入防止システム。中文：入侵防御系统检测并阻断恶意通信。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q43','exam-fe','ハッシュによるワーム検出','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問43・改編】ファイルのSHA-256ハッシュ値を求め、既知のワーム検体のハッシュ値データベースと照合する方式で検出できるものはどれか。','[{"id":"a","text":"既知の検体と同一のワーム"},{"id":"b","text":"既知検体と特徴的なコード列が同じワーム"},{"id":"c","text":"既知検体とファイルサイズが同じワーム"},{"id":"d","text":"既知検体の亜種に当たるワーム"}]','"a"','完全一致のハッシュ照合は既知の同一ファイルの検出に使う。亜種まで必ず検出できるわけではない。中文：完整文件哈希匹配用于识别已知相同样本，不能保证发现变种。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q44','exam-fe','ポートスキャナ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問44・改編】Webサーバ検査でポートスキャナを使う目的はどれか。','[{"id":"a","text":"稼働中のサービスを列挙し不要なサービスが動作していないか確認する"},{"id":"b","text":"利用者IDの管理状況を運用者に確認する"},{"id":"c","text":"アクセス履歴を解析し不正利用を検出する"},{"id":"d","text":"正規IDでログインしコンテンツを直接確認する"}]','"a"','ポートスキャンは応答するポートなどから稼働サービスを調査する。中文：端口扫描通过端口响应等识别运行的服务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption');
